export type Program = {
  id: string;
  universityId: string;
  name: string;
  field: FieldId;
  degree: string;
  /** Accepted elective subjects (one of). */
  electives: SubjectId[];
  /** Demo coefficients per subject. */
  coefficients: Partial<Record<SubjectId, number>>;
  /** Demo competition-score threshold on the 0–100 demo scale. */
  sampleCutoff: number;
  /** Demo annual tuition, GEL. */
  tuition: number;
  stateGrant: boolean;
  scholarship: boolean;
  seats: number;
  blurb: string;
};

const p = (
  id: string,
  universityId: string,
  name: string,
  field: FieldId,
  electives: SubjectId[],
  coef: Partial<Record<SubjectId, number>>,
  sampleCutoff: number,
  tuition: number,
  stateGrant: boolean,
  scholarship: boolean,
  seats: number,
  blurb: string,
  degree?: string,
): Program => ({
  id,
  universityId,
  name,
  field,
  degree: degree ?? (field === "medicine" ? "ერთსაფეხურიანი (მაგისტრი)" : "ბაკალავრიატი"),
  electives,
  coefficients: coef,
  sampleCutoff,
  tuition,
  stateGrant,
  scholarship,
  seats,
  blurb,
});

