export const universityById = (id: string): University => {
  const university = UNIVERSITIES.find((u) => u.id === id);
  if (!university) throw new Error(`Unknown university: ${id}`);
  return university;
};
export const programById = (id: string) => PROGRAMS.find((x) => x.id === id);
export const fieldName = (id?: FieldId | null) => FIELDS.find((f) => f.id === id)?.name ?? "არ არის არჩეული";
